const CATEGORY_REQUIREMENTS:Record<string,RequirementDefinition[]>={'transport-mobility':[{key:'origin',label:'Pickup/origin',required:true},{key:'destination',label:'Destination',required:true},{key:'departure_time',label:'When'}],'food-drink':[{key:'items',label:'Items or service',required:true},{key:'location',label:'Location',required:true},{key:'time',label:'When'}],'repairs-maintenance':[{key:'service',label:'What needs fixing',required:true},{key:'location',label:'Location',required:true},{key:'urgency',label:'Urgency'}],'events-entertainment':[{key:'event_type',label:'Event',required:true},{key:'event_date',label:'Date',required:true},{key:'location',label:'Location',required:true},{key:'budget',label:'Budget'}],'classifieds-marketplace':[{key:'item',label:'What you need',required:true},{key:'budget',label:'Budget'},{key:'location',label:'Preferred area'}],'gigs-microtasks':[{key:'service',label:'Job',required:true},{key:'location',label:'Location',required:true},{key:'time',label:'When'},{key:'budget',label:'Budget'}],'security-safety':[{key:'service',label:'Security need',required:true},{key:'location',label:'Location',required:true},{key:'date_time',label:'Date and time'}],'professional-services':[{key:'outcome',label:'Outcome needed',required:true},{key:'location',label:'Location'},{key:'deadline',label:'Deadline'},{key:'budget',label:'Budget'}],'sports-recreation':[{key:'activity',label:'Sport or activity',required:true},{key:'location',label:'Location',required:true},{key:'time',label:'When'},{key:'participants',label:'Participants'}]};
function requirementsForSkill(skill:string,category?:string):RequirementDefinition[]{return (REQUIREMENTS_BY_SKILL[skill]||CATEGORY_REQUIREMENTS[category||'']||[{key:'service',label:'What do you need?',required:true},{key:'location',label:'Location'},{key:'time',label:'When'}]).map(r=>({...r}));}
export function getEconomicCategory(skill:string):string|null{return CATEGORY_BY_SKILL[skill.trim().toLowerCase()]||null;}
export function getKnownSkills():string[]{return Object.keys(CATEGORY_BY_SKILL);}
export function getSkillRequirements(skill:string):RequirementDefinition[]{const normalized=skill.trim().toLowerCase();return requirementsForSkill(normalized,getEconomicCategory(normalized)||undefined);}
export function getDefaultCapabilities(category?:string):EconomicCapability[]{const c=[...DEFAULT_CAPABILITIES];if(['events-entertainment','professional-services','property-real-estate','legal-compliance'].includes(category||''))c.splice(5,0,'contract');if(['transport-mobility','logistics-freight','errands-delivery'].includes(category||''))c.splice(7,0,'tracking');if(['repairs-maintenance','health-medical','classifieds-marketplace'].includes(category||''))c.splice(8,0,'evidence');return Array.from(new Set<EconomicCapability>(c));}
export function getSkillCapabilities(skill:string):EconomicCapability[]{const normalized=skill.trim().toLowerCase();const category=getEconomicCategory(normalized)||undefined;const capabilities=getDefaultCapabilities(category);if(normalized==='verified_artist')return Array.from(new Set<EconomicCapability>([...capabilities,'contract','escrow']));if(['buy_car','product_sourcing'].includes(normalized))return Array.from(new Set<EconomicCapability>([...capabilities,'evidence','escrow']));if(normalized==='buy_ticket')return Array.from(new Set<EconomicCapability>([...capabilities,'evidence']));return capabilities;}

export interface IntentSuggestion { label:string; prompt:string; }
const CONTEXTUAL_SUGGESTIONS:Record<string,IntentSuggestion[]>={
  order_food:[{label:'Find food',prompt:'Help me find food nearby'},{label:'Get groceries',prompt:'Help me get groceries'},{label:'Find somewhere nearby',prompt:'What food is nearby?'}],
  find_worker:[{label:'Find a repairer',prompt:'Help me find a repairer'},{label:'Request roadside help',prompt:'I need roadside help'},{label:'Find a tow service',prompt:'Help me find a tow service'}],
  ride_request:[{label:'Choose a ride',prompt:'I need a ride'},{label:'Find a driver',prompt:'Help me find a driver nearby'},{label:'Plan a trip',prompt:'Help me plan a trip'}],
  reminder:[{label:'Create reminder',prompt:'Create a reminder'},{label:'Set reminder date',prompt:'Set a reminder date'},{label:'View reminders',prompt:'Show my reminders'}],
  safety_contact:[{label:'Add emergency contact',prompt:'Add an emergency contact'},{label:'Start safety check-in',prompt:'Set a safety check-in'},{label:'Get urgent guidance',prompt:'I need urgent safety help'}],
  sports_matchmaking:[{label:'Find players',prompt:'Help me find players nearby'},{label:'Create a match',prompt:'Create a sports match'},{label:'Find a pitch',prompt:'Help me find a pitch'}]
};
const CATEGORY_SUGGESTION_KEY:Record<string,string>={'food-drink':'order_food','cravings-streetfood':'order_food','repairs-maintenance':'find_worker','automotive-mechanics':'find_worker','transport-mobility':'ride_request','sports-recreation':'sports_matchmaking'};
export function getContextualIntentSuggestions(skill:string,max=3):IntentSuggestion[]{const normalized=skill.trim().toLowerCase();const category=getEconomicCategory(normalized)||'';const key=CONTEXTUAL_SUGGESTIONS[normalized]?normalized:(CATEGORY_SUGGESTION_KEY[category]||'');return (CONTEXTUAL_SUGGESTIONS[key]||[]).slice(0,Math.max(0,max)).map(item=>({...item}));}
function normalize(row:any):SkillFlow|null{if(!row)return null;const skill=String(row.skill||'').trim();if(!skill)return null;const category=getEconomicCategory(skill);return{skill,question_set:String(row.question_set||'').trim(),post_match_action:String(row.post_match_action||'').trim(),payment_model:String(row.payment_model||'').trim(),fulfillment_instructions:String(row.fulfillment_instructions||'').trim(),capabilities:getSkillCapabilities(skill),category:category||undefined,requirements:getSkillRequirements(skill)};}

